class Solution { public: int findLeastNumOfUniqueInts(vector<int>& arr,int k){unordered_map<int,int> count;for(int value:arr)++count[value];vector<int> frequencies;for(auto [value,frequency]:count)frequencies.push_back(frequency);sort(frequencies.begin(),frequencies.end());int unique=frequencies.size();for(int frequency:frequencies){if(k<frequency)break;k-=frequency;--unique;}return unique;} };
